package interp

import (
	"context"
	"errors"
	"fmt"
	"go/token"
	"io/fs"
	"path"
	"path/filepath"
	"reflect"
	"sort"
	"sync"
)

var (
	// ErrNotLive indicates that the specified ID does not refer to a (live) Go
	// routine.
	ErrNotLive = errors.New("not live")

	// ErrRunning indicates that the specified Go routine is running.
	ErrRunning = errors.New("running")

	// ErrNotRunning indicates that the specified Go routine is running.
	ErrNotRunning = errors.New("not running")
)

var rNodeType = reflect.TypeOf((*node)(nil)).Elem()

// A Debugger can be used to debug a Yaegi program.
type Debugger struct {
	interp  *Interpreter
	events  func(*DebugEvent)
	context context.Context
	cancel  context.CancelFunc

	gWait               *sync.WaitGroup
	gLock               *sync.Mutex
	gID                 int
	gLive               map[int]*debugRoutine
	main                *debugRoutine
	workers             int  // owned goroutines, including compiled calls without source frames
	nativeValuesEscaped bool // mutable aliases may outlive compiled dispatch

	result     reflect.Value
	err        error
	done       chan struct{}
	terminated bool
}

// go routine debug state.
type debugRoutine struct {
	id    int
	kind  string
	mutex sync.Mutex

	mode    DebugEventReason
	running bool
	resume  chan struct{}

	fDepth      int
	fStep       int
	stoppedFile string
	stoppedLine int
	stepFile    string
	stepLine    int
}

// node debug state.
type nodeDebugData struct {
	program     *Program
	breakOnLine bool
	breakOnCall bool
}

// frame debug state.
type frameDebugData struct {
	g              *debugRoutine
	node           *node
	name           string
	kind           frameKind
	scope          *scope
	caller         *frame // actual synchronous caller, independent of lexical capture
	nativeBoundary bool
}

// frame kind.
type frameKind int

const (
	// interpreter root frame.
	frameRoot frameKind = iota + 1

	// function call frame.
	frameCall

	// closure capture frame.
	frameClosure
)

// DebugOptions are the debugger options.
type DebugOptions struct {
	// If true, Go routine IDs start at 1 instead of 0.
	GoRoutineStartAt1 bool
}

// A DebugEvent is an event generated by a debugger.
type DebugEvent struct {
	debugger *Debugger
	reason   DebugEventReason
	frame    *frame
}

// DebugFrame provides access to stack frame information while debugging a
// program.
type DebugFrame struct {
	event  *DebugEvent
	frames []*frame
}

// DebugFrameScope provides access to scoped variables while debugging a
// program.
type DebugFrameScope struct {
	frame *frame
}

// DebugVariable is the name and value of a variable from a debug session.
type DebugVariable struct {
	Name  string
	Value reflect.Value
}

// DebugGoRoutine provides access to information about a Go routine while
// debugging a program.
type DebugGoRoutine struct {
	id   int
	kind string
}

// Breakpoint is the result of attempting to set a breakpoint.
type Breakpoint struct {
	// Valid indicates whether the breakpoint was successfully set.
	Valid bool

	// Position indicates the source position of the breakpoint.
	Position token.Position
}

// DebugEventReason is the reason a debug event occurred.
type DebugEventReason int

const (
	// continue execution normally.
	debugRun DebugEventReason = iota

	// DebugPause is emitted when a pause request is completed. Can be used with
	// Interrupt to request a pause.
	DebugPause

	// DebugBreak is emitted when a debug target hits a breakpoint.
	DebugBreak

	// DebugEntry is emitted when a debug target starts executing. Can be used
	// with Step to produce a corresponding event when execution starts.
	DebugEntry

	// DebugStepInto is emitted when a stepInto request is completed. Can be
	// used with Step or Interrupt to request a stepInto.
	DebugStepInto

	// DebugStepOver is emitted when a stepOver request is completed. Can be
	// used with Step or Interrupt to request a stepOver.
	DebugStepOver

	// DebugStepOut is emitted when a stepOut request is completed. Can be used
	// with Step or Interrupt to request a stepOut.
	DebugStepOut

	// DebugTerminate is emitted when a debug target terminates. Can be used
	// with Interrupt to attempt to terminate the program.
	DebugTerminate

	// DebugEnterGoRoutine is emitted when a Go routine is entered.
	DebugEnterGoRoutine

	// DebugExitGoRoutine is emitted when a Go routine is exited.
	DebugExitGoRoutine
)

// Debug initializes a debugger for the given program.
//
// The program will not start running until Step or Continue has been called. If
// Step is called with DebugEntry, an entry event will be generated before the
// first statement is executed. Otherwise, the debugger will behave as usual.
func (interp *Interpreter) Debug(ctx context.Context, prog *Program, events func(*DebugEvent), opts *DebugOptions) *Debugger {
	execution := interp.newExecution()
	return interp.debug(ctx, prog, []*node{prog.root}, events, opts, func(ctx context.Context) (reflect.Value, error) {
		return execution.evaluate(ctx, func() (reflect.Value, error) { return interp.Execute(prog) })
	}, execution.close)
}

func (interp *Interpreter) newDebugger(ctx context.Context, events func(*DebugEvent), opts *DebugOptions) *Debugger {
	dbg := new(Debugger)
	dbg.interp = interp
	dbg.events = events
	dbg.context, dbg.cancel = context.WithCancel(ctx)
	dbg.gWait = new(sync.WaitGroup)
	dbg.gLock = new(sync.Mutex)
	dbg.gLive = make(map[int]*debugRoutine, 1)
	dbg.done = make(chan struct{})

	if opts == nil {
		opts = new(DebugOptions)
	}
	if opts.GoRoutineStartAt1 {
		dbg.gID = 1
	}

	dbg.main = dbg.enterGoRoutine()
	interp.debugger = dbg
	interp.frame.debug = &frameDebugData{kind: frameRoot, g: dbg.main}
	return dbg
}

func (interp *Interpreter) debug(ctx context.Context, prog *Program, roots []*node, events func(*DebugEvent), opts *DebugOptions, execute func(context.Context) (reflect.Value, error), finish func() error) *Debugger {
	dbg := interp.newDebugger(ctx, events, opts)
	dbg.start(prog, roots, execute, finish)
	return dbg
}

func (dbg *Debugger) start(prog *Program, roots []*node, execute func(context.Context) (reflect.Value, error), finish func() error) {
	interp := dbg.interp
	mainG := dbg.main
	mainG.mutex.Lock()
	mainG.mode = DebugEntry
	// Source dependency initialization may already have used this routine in
	// run mode. The entry barrier is stopped regardless of that earlier work.
	mainG.running = false
	mainG.mutex.Unlock()

	for _, root := range roots {
		root.Walk(func(n *node) bool { n.setProgram(prog); return true }, nil)
	}

	go func() {
		defer close(dbg.done)
		defer func() {
			if r := recover(); r != nil {
				dbg.err = recoveredPanic(r)
			}
			dbg.cancel()
			if err := finish(); dbg.err == nil {
				dbg.err = err
			}
			dbg.exitGoRoutine(mainG)
			dbg.events(&DebugEvent{dbg, DebugExitGoRoutine, interp.frame})
			dbg.gWait.Wait()
			dbg.events(&DebugEvent{debugger: dbg, reason: DebugTerminate})
		}()
		select {
		case <-mainG.resume:
			dbg.events(&DebugEvent{dbg, DebugEnterGoRoutine, interp.frame})
			dbg.result, dbg.err = execute(dbg.context)
		case <-dbg.context.Done():
			dbg.err = dbg.context.Err()
		}
	}()
}

// Wait blocks until all Go routines launched by the program have terminated.
// Wait returns the results of `(*Interpreter).Execute`.
func (dbg *Debugger) Wait() (reflect.Value, error) {
	<-dbg.done
	return dbg.result, dbg.err
}

// mark entry into a go routine.
func (dbg *Debugger) enterGoRoutine() *debugRoutine {
	return dbg.enterRoutine("goroutine")
}

// enterRoutine registers either an interpreted goroutine or a logical opaque
// native callback owner. The kind is immutable before the owner becomes live.
func (dbg *Debugger) enterRoutine(kind string) *debugRoutine {
	g := new(debugRoutine)
	g.kind = kind
	g.resume = make(chan struct{}, 1)

	dbg.gWait.Add(1)

	dbg.gLock.Lock()
	g.id = dbg.gID
	dbg.gID++
	if dbg.terminated {
		g.mode = DebugTerminate
	}
	dbg.gLive[g.id] = g
	dbg.gLock.Unlock()

	return g
}

// trackWorker closes the scheduling-to-frame-registration gap, and also counts
// compiled go calls which never enter an interpreted call frame. The epoch owns
// their lifetime; this count only controls safe stopped-value snapshots.
func (dbg *Debugger) trackWorker() func() {
	dbg.gLock.Lock()
	dbg.workers++
	dbg.gLock.Unlock()
	return func() {
		dbg.gLock.Lock()
		dbg.workers--
		dbg.gLock.Unlock()
	}
}

// mark exit from a go routine.
func (dbg *Debugger) exitGoRoutine(g *debugRoutine) {
	dbg.gLock.Lock()
	if dbg.gLive[g.id] != g {
		dbg.gLock.Unlock()
		return
	}
	delete(dbg.gLive, g.id)
	dbg.gLock.Unlock()

	dbg.gWait.Done()
}

// get the state for a given go routine, if it's live.
func (dbg *Debugger) getGoRoutine(id int) (*debugRoutine, bool) {
	dbg.gLock.Lock()
	g, ok := dbg.gLive[id]
	dbg.gLock.Unlock()
	return g, ok
}

// mark entry into a function call.
func (dbg *Debugger) enterCall(nFunc, nCall *node, f *frame) {
	if f.debug != nil {
		f.debug.g.mutex.Lock()
		f.debug.g.fDepth++
		f.debug.g.mutex.Unlock()
		return
	}

	f.debug = new(frameDebugData)
	f.debug.g = f.anc.debug.g
	f.debug.scope = nFunc.scope

	switch nFunc.kind {
	case funcLit:
		f.debug.kind = frameCall

	case funcDecl:
		f.debug.kind = frameCall
		f.debug.name = nFunc.child[1].ident
	}

	if nCall != nil && nCall.anc.kind == goStmt {
		f.debug.g = dbg.enterGoRoutine()
		dbg.events(&DebugEvent{dbg, DebugEnterGoRoutine, f})
	}

	f.debug.g.mutex.Lock()
	f.debug.g.fDepth++
	f.debug.g.mutex.Unlock()
}

// mark exit from a function call.
func (dbg *Debugger) exitCall(nFunc, nCall *node, f *frame) {
	_ = nFunc // ignore unused, so exitCall can have the same signature as enterCall

	f.debug.g.mutex.Lock()
	f.debug.g.fDepth--
	f.debug.g.mutex.Unlock()

	if nCall != nil && nCall.anc.kind == goStmt {
		dbg.exitGoRoutine(f.debug.g)
		dbg.events(&DebugEvent{dbg, DebugExitGoRoutine, f})
	}
}

// called by the interpreter prior to executing the node.
func (dbg *Debugger) exec(n *node, f *frame) (stop bool) {
	f.debug.node = n

	if n != nil && n.pos == token.NoPos {
		return false
	}

	g := f.debug.g
	g.mutex.Lock()
	var position token.Position
	if n != nil {
		position = dbg.interp.fset.Position(n.pos)
	}

	e := &DebugEvent{dbg, g.mode, f}
	switch {
	case g.mode == DebugTerminate:
		g.mutex.Unlock()
		dbg.cancel()
		return true

	case n.shouldBreak():
		e.reason = DebugBreak

	case g.mode == debugRun:
		g.running = true
		g.mutex.Unlock()
		return false

	case g.mode == DebugStepOut:
		if g.fDepth >= g.fStep {
			g.mutex.Unlock()
			return false
		}

	case g.mode == DebugStepOver:
		if g.fDepth > g.fStep {
			g.mutex.Unlock()
			return false
		}
	}
	if (g.mode == DebugStepInto || g.mode == DebugStepOver) && e.reason != DebugBreak && position.Filename == g.stepFile && position.Line == g.stepLine {
		g.mutex.Unlock()
		return false
	}
	g.running = false
	g.stoppedFile, g.stoppedLine = position.Filename, position.Line
	g.mutex.Unlock()
	// Mark stopped before publishing the event. A command may now queue a
	// buffered resume while the callback snapshots the still-stopped frame.
	dbg.events(e)
	select {
	case <-g.resume:
		return false
	case <-dbg.context.Done():
		return true
	}
}

// Continue continues execution of the specified Go routine. Continue returns
// ErrNotLive if there is no Go routine with the corresponding ID, or if it is not
// live.
func (dbg *Debugger) Continue(id int) error {
	g, ok := dbg.getGoRoutine(id)
	if !ok {
		return ErrNotLive
	}
	g.mutex.Lock()
	defer g.mutex.Unlock()
	if g.mode == DebugTerminate {
		return ErrNotLive
	}
	if g.running {
		return ErrRunning
	}
	g.mode = debugRun
	g.running = true
	select {
	case g.resume <- struct{}{}:
	default:
	}
	return nil
}

// update the exec mode of this routine.
func (g *debugRoutine) setMode(reason DebugEventReason) {
	if g.mode == DebugTerminate {
		return
	}

	if g.mode == DebugEntry && reason == DebugEntry {
		return
	}

	switch reason {
	case DebugStepInto, DebugStepOver, DebugStepOut:
		g.mode, g.fStep = reason, g.fDepth
		g.stepFile, g.stepLine = g.stoppedFile, g.stoppedLine
	default:
		g.mode = DebugPause
	}
}

// Step issues a stepInto, stepOver, or stepOut request to a stopped Go routine.
// Step returns ErrRunning if the Go routine is running. Step returns ErrNotLive
// if there is no Go routine with the corresponding ID, or if it is not live.
func (dbg *Debugger) Step(id int, reason DebugEventReason) error {
	g, ok := dbg.getGoRoutine(id)
	if !ok {
		return ErrNotLive
	}
	g.mutex.Lock()
	defer g.mutex.Unlock()
	if g.mode == DebugTerminate {
		return ErrNotLive
	}
	if g.running {
		return ErrRunning
	}

	g.setMode(reason)
	g.running = true
	select {
	case g.resume <- struct{}{}:
	default:
	}
	return nil
}

// Interrupt issues a stepInto, stepOver, or stepOut request to a running Go
// routine. Interrupt returns ErrRunning if the Go routine is running. Interrupt
// returns ErrNotLive if there is no Go routine with the corresponding ID, or if
// it is not live.
func (dbg *Debugger) Interrupt(id int, reason DebugEventReason) bool {
	g, ok := dbg.getGoRoutine(id)
	if !ok {
		return false
	}
	g.mutex.Lock()
	defer g.mutex.Unlock()
	g.setMode(reason)
	return true
}

// Terminate attempts to terminate the program.
func (dbg *Debugger) Terminate() {
	dbg.gLock.Lock()
	dbg.terminated = true
	g := make([]*debugRoutine, 0, len(dbg.gLive))
	for _, routine := range dbg.gLive {
		g = append(g, routine)
	}
	dbg.gLock.Unlock()

	for _, g := range g {
		g.mutex.Lock()
		g.mode = DebugTerminate
		select {
		case g.resume <- struct{}{}:
		default:
		}
		g.mutex.Unlock()
	}
	dbg.cancel()
}

// BreakpointTarget is the target of a request to set breakpoints.
type BreakpointTarget func(*Debugger, func(*node))

// PathBreakpointTarget is used to set breapoints on compiled code by path. This
// can be used to set breakpoints on code compiled with EvalPath, or source
// packages loaded by Yaegi.
func PathBreakpointTarget(path string) BreakpointTarget {
	return func(dbg *Debugger, cb func(*node)) {
		for _, r := range dbg.interp.roots {
			f := dbg.interp.fset.File(r.pos)
			if f != nil && f.Name() == path {
				cb(r)
				return
			}
		}
	}
}

// ProgramBreakpointTarget is used to set breakpoints on a Program.
func ProgramBreakpointTarget(prog *Program) BreakpointTarget {
	return func(_ *Debugger, cb func(*node)) {
		cb(prog.root)
	}
}

// AllBreakpointTarget is used to set breakpoints on all compiled code. Do not
// use with LineBreakpoint.
func AllBreakpointTarget() BreakpointTarget {
	return func(dbg *Debugger, cb func(*node)) {
		for _, r := range dbg.interp.roots {
			cb(r)
		}
	}
}

type breakpointSetup struct {
	roots []*node
	lines map[int]int
	funcs map[string]int
}

// BreakpointRequest is a request to set a breakpoint.
type BreakpointRequest func(*breakpointSetup, int)

// LineBreakpoint requests a breakpoint on the given line.
func LineBreakpoint(line int) BreakpointRequest {
	return func(b *breakpointSetup, i int) {
		b.lines[line] = i
	}
}

// FunctionBreakpoint requests a breakpoint on the named function.
func FunctionBreakpoint(name string) BreakpointRequest {
	return func(b *breakpointSetup, i int) {
		b.funcs[name] = i
	}
}

// SetBreakpoints sets breakpoints for the given target. The returned array has
// an entry for every request, in order. If a given breakpoint request cannot be
// satisfied, the corresponding entry will be marked invalid. If the target
// cannot be found, all entries will be marked invalid.
func (dbg *Debugger) SetBreakpoints(target BreakpointTarget, requests ...BreakpointRequest) []Breakpoint {
	// start with all breakpoints unverified
	results := make([]Breakpoint, len(requests))

	// prepare all the requests
	setup := new(breakpointSetup)
	target(dbg, func(root *node) {
		setup.roots = append(setup.roots, root)
		setup.lines = make(map[int]int, len(requests))
		setup.funcs = make(map[string]int, len(requests))
		for i, rq := range requests {
			rq(setup, i)
		}
	})

	// find breakpoints
	for _, root := range setup.roots {
		root.Walk(func(n *node) bool {
			// function breakpoints
			if len(setup.funcs) > 0 && n.kind == funcDecl {
				// reset stale breakpoints
				n.start.setBreakOnCall(false)

				if i, ok := setup.funcs[n.child[1].ident]; ok && !results[i].Valid {
					results[i].Valid = true
					results[i].Position = dbg.interp.fset.Position(n.start.pos)
					n.start.setBreakOnCall(true)
					return true
				}
			}

			// line breakpoints
			if len(setup.lines) > 0 && n.pos.IsValid() && n.action != aNop && getExec(n) != nil {
				// reset stale breakpoints
				n.setBreakOnLine(false)

				pos := dbg.interp.fset.Position(n.pos)
				if i, ok := setup.lines[pos.Line]; ok && !results[i].Valid {
					results[i].Valid = true
					results[i].Position = pos
					n.setBreakOnLine(true)
					return true
				}
			}

			return true
		}, nil)
	}

	return results
}

// GoRoutines returns an array of live Go routines.
func (dbg *Debugger) GoRoutines() []*DebugGoRoutine {
	dbg.gLock.Lock()
	r := make([]*DebugGoRoutine, 0, len(dbg.gLive))
	for id, g := range dbg.gLive {
		r = append(r, &DebugGoRoutine{id: id, kind: g.kind})
	}
	dbg.gLock.Unlock()
	sort.Slice(r, func(i, j int) bool { return r[i].id < r[j].id })
	return r
}

// ID returns the ID of the Go routine.
func (r *DebugGoRoutine) ID() int { return r.id }

// Kind identifies an interpreted goroutine or a logical native callback owner.
func (r *DebugGoRoutine) Kind() string { return r.kind }

// Name returns the execution owner's display name.
func (r *DebugGoRoutine) Name() string {
	if r.kind == "nativeCallback" {
		return fmt.Sprintf("Native callback %d", r.id)
	}
	return fmt.Sprintf("Goroutine %d", r.id)
}

// GoRoutine returns the ID of the Go routine that generated the event.
func (evt *DebugEvent) GoRoutine() int {
	if evt.frame == nil || evt.frame.debug == nil || evt.frame.debug.g == nil {
		return 0
	}
	return evt.frame.debug.g.id
}

// GoRoutineKind remains available even after this event's owner has exited.
func (evt *DebugEvent) GoRoutineKind() string {
	if evt.frame == nil || evt.frame.debug == nil || evt.frame.debug.g == nil {
		return "goroutine"
	}
	return evt.frame.debug.g.kind
}

// OpaqueNativeBoundary reports that the caller beyond this execution owner is
// unknown. Captured lexical frames must not be displayed or inspected as callers.
func (evt *DebugEvent) OpaqueNativeBoundary() bool {
	return evt.GoRoutineKind() == "nativeCallback"
}

// WithStoppedValues runs a bounded scalar-only snapshot while this event is the
// sole stopped owner and no owned worker can execute. Registration and resume
// are excluded until snapshot returns. The callback must not reenter debugger
// APIs, execute user code, dereference native pointers or inspect aggregates.
// Mutable aliases exposed to compiled code make values unavailable for the
// remainder of the session; native completion cannot prove release of an alias.
func (evt *DebugEvent) WithStoppedValues(snapshot func()) bool {
	if evt.frame == nil || evt.frame.debug == nil || evt.OpaqueNativeBoundary() {
		return false
	}
	dbg, g := evt.debugger, evt.frame.debug.g
	if dbg == nil || g == nil {
		return false
	}
	dbg.gLock.Lock()
	defer dbg.gLock.Unlock()
	if len(dbg.gLive) != 1 || dbg.gLive[g.id] != g || dbg.workers != 0 || dbg.nativeValuesEscaped {
		return false
	}
	g.mutex.Lock()
	defer g.mutex.Unlock()
	if g.running || g.mode == DebugTerminate {
		return false
	}
	snapshot()
	return true
}

// NativeValuesEscaped reports the sticky reason scalar snapshots are disabled.
func (evt *DebugEvent) NativeValuesEscaped() bool {
	if evt.debugger == nil {
		return false
	}
	evt.debugger.gLock.Lock()
	defer evt.debugger.gLock.Unlock()
	return evt.debugger.nativeValuesEscaped
}

// Reason returns the reason for the event.
func (evt *DebugEvent) Reason() DebugEventReason {
	return evt.reason
}

// Walk the stack trace frames. The root frame is included if and only if it is
// the only frame. Closure frames are rolled up into the following call frame.
func (evt *DebugEvent) walkFrames(fn func([]*frame) bool) {
	if evt.frame == nil {
		return
	}
	if evt.frame == evt.frame.root {
		fn([]*frame{evt.frame})
		return
	}

	var g *debugRoutine
	if evt.frame.debug != nil {
		g = evt.frame.debug.g
	}

	var frames []*frame
	for f := evt.frame; f != nil && f != f.root && (f.debug == nil || f.debug.g == g); {
		current := f
		f = current.anc
		if current.debug != nil && current.debug.caller != nil {
			f = current.debug.caller
		}
		if current.debug == nil || current.debug.kind != frameCall {
			frames = append(frames, current)
			continue
		}

		if len(frames) > 0 {
			if !fn(frames) {
				return
			}
		}

		frames = frames[:0]
		frames = append(frames, current)
		if current.debug.nativeBoundary {
			break
		}
	}

	if len(frames) > 0 {
		fn(frames)
	}
}

// FrameDepth returns the number of call frames in the stack trace.
func (evt *DebugEvent) FrameDepth() int {
	if evt.frame == nil {
		return 0
	}
	if evt.frame == evt.frame.root {
		return 1
	}

	var n int
	evt.walkFrames(func([]*frame) bool { n++; return true })
	return n
}

// Frames returns the call frames in the range [start, end).
func (evt *DebugEvent) Frames(start, end int) []*DebugFrame {
	count := end - start
	if count < 0 {
		return nil
	}

	frames := []*DebugFrame{}
	evt.walkFrames(func(f []*frame) bool {
		df := &DebugFrame{evt, make([]*frame, len(f))}
		copy(df.frames, f)
		frames = append(frames, df)
		return len(frames) < count
	})
	return frames
}

// OpaqueNativeBoundary identifies the final source frame at an opaque entry.
func (f *DebugFrame) OpaqueNativeBoundary() bool {
	for _, current := range f.frames {
		if current.debug != nil && current.debug.nativeBoundary {
			return true
		}
	}
	return false
}

// Name returns the name of the stack frame. For function calls to named
// functions, this is the function name.
func (f *DebugFrame) Name() string {
	d := f.frames[0].debug
	if d == nil {
		return "<unknown>"
	}
	switch d.kind {
	case frameRoot:
		return "<init>"
	case frameClosure:
		return "<closure>"
	case frameCall:
		if d.name == "" {
			return "<anonymous>"
		}
		return d.name
	default:
		return "<unknown>"
	}
}

// Position returns the current position of the frame. This is effectively the
// program counter/link register. May return `Position{}`.
func (f *DebugFrame) Position() token.Position {
	d := f.frames[0].debug
	if d == nil || d.node == nil {
		return token.Position{}
	}
	return f.event.debugger.interp.fset.Position(d.node.pos)
}

// Program returns the program associated with the current position of the
// frame. May return nil.
func (f *DebugFrame) Program() *Program {
	d := f.frames[0].debug
	if d == nil || d.node == nil || d.node.debug == nil {
		return nil
	}

	return d.node.debug.program
}

// Scopes returns the variable scopes of the frame.
func (f *DebugFrame) Scopes() []*DebugFrameScope {
	s := make([]*DebugFrameScope, len(f.frames))
	for i, f := range f.frames {
		s[i] = &DebugFrameScope{f}
	}
	return s
}

// IsClosure returns true if this is the capture scope of a closure.
func (f *DebugFrameScope) IsClosure() bool {
	return f.frame.debug != nil && f.frame.debug.kind == frameClosure
}

// Variables returns the names and values of the variables of the scope.
func (f *DebugFrameScope) Variables() []*DebugVariable {
	d := f.frame.debug
	if d == nil || d.scope == nil {
		return nil
	}

	index := map[int]string{}
	scanScope(d.scope, index)

	m := make([]*DebugVariable, 0, len(f.frame.data))
	for i, v := range f.frame.data {
		if typ := v.Type(); typ.AssignableTo(rNodeType) || typ.Kind() == reflect.Ptr && typ.Elem().AssignableTo(rNodeType) {
			continue
		}
		name, ok := index[i]
		if !ok {
			continue
		}

		m = append(m, &DebugVariable{name, v})
	}
	return m
}

func scanScope(sc *scope, index map[int]string) {
	for name, sym := range sc.sym {
		if _, ok := index[sym.index]; ok {
			continue
		}
		index[sym.index] = name
	}

	for _, ch := range sc.child {
		if ch.def != sc.def {
			continue
		}
		scanScope(ch, index)
	}
}

// DebugPath prepares a main package without executing its globals, init or main.
// Unlike CompilePath(directory), it preserves every file's scope and defers the
// entry package's execution until a debugger command. Imported source packages
// retain Yaegi's existing import-time initialization semantics.
func (interp *Interpreter) DebugPath(ctx context.Context, importPath string, events func(*DebugEvent), opts *DebugOptions) (*Debugger, error) {
	type packageProgram struct {
		program *Program
		roots   []*node
		scope   *scope
	}
	var compiled *packageProgram
	execution := interp.newExecution()
	// Attach before imports in run mode so dependency-created callbacks keep
	// valid debug ancestry, without pausing before the entry package is ready.
	dbg := interp.newDebugger(ctx, events, opts)
	_, err := execution.evaluate(dbg.context, func() (reflect.Value, error) {
		dir, rPath, err := interp.pkgDir(filepath.ToSlash(interp.context.GOPATH), mainID, importPath)
		if err != nil {
			return reflect.Value{}, err
		}
		files, err := fs.ReadDir(interp.opt.filesystem, dir)
		if err != nil {
			return reflect.Value{}, err
		}
		var roots []*node
		var initializers []*node
		var pkgName string
		revisit := make(map[string][]*node)
		for _, file := range files {
			if skipFile(&interp.context, file.Name(), NoTest) {
				continue
			}
			name := path.Join(dir, file.Name())
			source, err := fs.ReadFile(interp.opt.filesystem, name)
			if err != nil {
				return reflect.Value{}, err
			}
			parsed, err := interp.parse(string(source), name, false)
			if err != nil {
				return reflect.Value{}, err
			}
			if parsed == nil {
				continue
			}
			pname, root, err := interp.ast(parsed)
			if err != nil {
				return reflect.Value{}, err
			}
			if root == nil {
				continue
			}
			if pkgName == "" {
				pkgName = pname
			} else if pkgName != pname {
				return reflect.Value{}, fmt.Errorf("found packages %s and %s in %s", pkgName, pname, dir)
			}
			roots = append(roots, root)
			subRPath := effectivePkg(rPath, importPath)
			list, err := interp.gta(root, subRPath, importPath, pkgName)
			if err != nil {
				return reflect.Value{}, err
			}
			revisit[subRPath] = append(revisit[subRPath], list...)
		}
		for _, nodes := range revisit {
			if err := interp.gtaRetry(nodes, importPath, pkgName); err != nil {
				return reflect.Value{}, err
			}
		}
		for _, root := range roots {
			nodes, err := interp.cfg(root, nil, importPath, pkgName)
			if err != nil {
				return reflect.Value{}, err
			}
			initializers = append(initializers, nodes...)
		}
		gs := interp.scopes[importPath]
		if gs == nil || len(roots) == 0 {
			return reflect.Value{}, fmt.Errorf("no Go files in %s", dir)
		}
		main := gs.sym[mainID]
		if pkgName != mainID || main == nil {
			return reflect.Value{}, fmt.Errorf("no main function in %s", dir)
		}
		interp.srcPkg[importPath] = gs.sym
		interp.pkgNames[importPath] = pkgName
		initializers = append(initializers, main.node)
		compiled = &packageProgram{&Program{pkgName: pkgName, root: roots[0], init: initializers}, roots, gs}
		return reflect.Value{}, nil
	})
	if err != nil {
		dbg.Terminate()
		execution.close()
		dbg.exitGoRoutine(dbg.main)
		dbg.gWait.Wait()
		close(dbg.done)
		return nil, err
	}
	dbg.start(compiled.program, compiled.roots, func(ctx context.Context) (reflect.Value, error) {
		return execution.evaluate(ctx, func() (reflect.Value, error) {
			for _, root := range compiled.roots {
				if err := genRun(root); err != nil {
					return reflect.Value{}, err
				}
			}
			interp.frame.setrunid(interp.runid())
			interp.frame.mutex.Lock()
			interp.resizeFrame()
			interp.frame.mutex.Unlock()
			for _, root := range compiled.roots {
				interp.run(root, nil)
			}
			global, err := genGlobalVars(compiled.roots, compiled.scope)
			if err != nil {
				return reflect.Value{}, err
			}
			interp.run(global, nil)
			for _, initializer := range compiled.program.init {
				interp.run(initializer, interp.frame)
			}
			return reflect.Value{}, nil
		})
	}, execution.close)
	return dbg, nil
}

// debugExecuteContext owns a standalone debug evaluation epoch.
func (interp *Interpreter) debugExecuteContext(ctx context.Context, execute func() (reflect.Value, error)) (value reflect.Value, err error) {
	execution := interp.newExecution()
	defer func() {
		if failure := execution.close(); err == nil {
			err = failure
		}
	}()
	return execution.evaluate(ctx, execute)
}
